 const teacher=state.profile?.label||state.profile?.full_name||'';
 const today=new Date().toLocaleDateString('ar-SA');
 const body=rows.slice().sort((a,b)=>String(a.class_name||'').localeCompare(String(b.class_name||''),'ar')||String(a.full_name||'').localeCompare(String(b.full_name||''),'ar')).map((x,i)=>'<tr><td>'+fmt(i+1)+'</td><td class="name">'+esc(x.full_name)+'</td><td>'+esc(x.class_name||'—')+'</td><td class="issue">'+esc(nativeFollowIssue(x))+'</td><td>'+(x.last_activity_at?new Date(x.last_activity_at).toLocaleDateString('ar-SA'):'لم يبدأ')+'</td></tr>').join('');
